from collections import deque

def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Create a dictionary to map each bus stop to the list of buses that go through it
    stop_to_routes = {}
    for i, route in enumerate(routes):
        for stop in route:
            if stop not in stop_to_routes:
                stop_to_routes[stop] = []
            stop_to_routes[stop].append(i)

    # Use a queue to perform a BFS
    queue = deque([(S, 0)])  # (current_stop, buses_taken)
    visited_stops = set([S])
    visited_routes = set()

    while queue:
        current_stop, buses_taken = queue.popleft()

        for route_index in stop_to_routes[current_stop]:
            if route_index not in visited_routes:
                visited_routes.add(route_index)
                for next_stop in routes[route_index]:
                    if next_stop == T:
                        return buses_taken + 1
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append((next_stop, buses_taken + 1))

    return -1
